//! Standard library: `tallow.osint` -- OSINT intelligence types and operations.
//!
//! Provides Target seed types with provenance tracking, subdomain enumeration
//! via CT logs and DNS brute-force, and Wappalyzer-style technology fingerprinting.

use super::StdlibResult;
use crate::interp::Value;

use std::collections::HashSet;
use uuid::Uuid;

// ══════════════════════════════════════════════════════════════════
// Provenance helpers
// ══════════════════════════════════════════════════════════════════

/// Create a single Provenance struct value.
fn make_provenance(source: &str, operation: &str) -> Value {
    Value::Struct {
        name: "Provenance".to_string(),
        fields: vec![
            ("source".to_string(), Value::String(source.to_string())),
            ("operation".to_string(), Value::String(operation.to_string())),
            (
                "timestamp".to_string(),
                Value::String(chrono::Utc::now().to_rfc3339()),
            ),
        ],
    }
}

/// Build a rich W3C-PROV-style provenance record. Mirrors the PROV-DM
/// entity/activity/agent model: an entity was generated by an activity, some
/// of whose attributes (source, method, transform) are recorded so a claim
/// can be traced back to a specific source passage and transform. Each record
/// carries a unique provenance id so downstream artifacts can bind to it.
fn make_prov(source: &str, operation: &str, agent: &str, transform: &str) -> Value {
    Value::Struct {
        name: "Provenance".to_string(),
        fields: vec![
            (
                "provenance_id".to_string(),
                Value::String(format!("prov--{}", Uuid::new_v4())),
            ),
            ("source".to_string(), Value::String(source.to_string())),
            ("operation".to_string(), Value::String(operation.to_string())),
            ("agent".to_string(), Value::String(agent.to_string())),
            ("transform".to_string(), Value::String(transform.to_string())),
            (
                "timestamp".to_string(),
                Value::String(chrono::Utc::now().to_rfc3339()),
            ),
        ],
    }
}

/// Clone existing provenance and append a new entry.
fn chain_provenance(existing: &[Value], source: &str, operation: &str) -> Vec<Value> {
    let mut chain = existing.to_vec();
    chain.push(make_provenance(source, operation));
    chain
}

/// Governed HTTP GET for keyless/free data sources: rate-limited (2 rps),
/// backoff+retry on 429/5xx, retry of transient transport errors. Returns the
/// body on 200; returns an error string for any other status or transport
/// failure so callers surface a clean message.
fn governed_fetch(url: &str, headers: &[(String, String)]) -> Result<String, String> {
    governed_fetch_limiter(url, headers, &super::http::GOV_DEFAULT)
}

/// Governed HTTP GET honoring a specific per-provider rate governor.
fn governed_fetch_limiter(
    url: &str,
    headers: &[(String, String)],
    limiter: &std::sync::Mutex<super::http::RateGovernor>,
) -> Result<String, String> {
    let (status, body, _retries, rate_limited) = super::http::governed_get(url, headers, limiter, 3)?;
    if rate_limited {
        return Err(format!("rate limited (429) fetching {url}"));
    }
    if status != 200 {
        return Err(format!("HTTP {status} fetching {url}"));
    }
    Ok(body)
}

