/// Dispatch static function calls: Target.domain, Target.ip, etc.
pub fn dispatch(function: &str, args: Vec<Value>) -> Option<StdlibResult> {
    match function {
        "Target.domain" => Some(target_domain(args)),
        "Target.ip" => Some(target_ip(args)),
        "Target.email" => Some(target_email(args)),
        "shop-78.example" => Some(target_org(args)),
        "TechStack.detect" => Some(techstack_detect(args)),
        "DomainIntel.whois" => Some(domain_intel_whois(args)),
        "DomainIntel.dns_history" => Some(domain_intel_dns_history(args)),
        "ASNIntel.lookup" => Some(asn_intel_lookup(args)),
        "EmailIntel.from" => Some(email_intel_from(args)),
        "parse_document" => Some(parse_document(args)),
        "IntelGraph.new" => Some(intel_graph_new()),
        "IncrementalCollector.new" => Some(incremental_collector_new()),
        "ioc.enrich" | "IOCEnrichment.enrich" => Some(enrich_ioc(args)),
        "osint.analyze_text" => Some(osint_analyze_text(args)),
        "ScanScope.authorize" => Some(scan_scope_authorize(args)),
        "Scanner.scan" => Some(scanner_scan(args)),
        "IntelReport.build" => Some(intel_report_build(args)),
        "ScanDB.query" => Some(scan_db_query(args)),
        "WebArchive.snapshots" => Some(web_archive_snapshots(args)),
        "WebArchive.diff" => Some(web_archive_diff(args)),
        "WebArchive.save_page_now" => Some(web_archive_save_page_now(args)),
        "WebArchive.availability" => Some(web_archive_availability(args)),
        "CommonCrawl.snapshots" => Some(common_crawl_cdx(args)),
        "UsernameEnum.new" => Some(username_enum_new(args)),
        "UsernameEnum.check" => Some(username_enum_check_handle(args)),
        "Target.username" => Some(target_username(args)),
        "Phone.lookup" => Some(phone_lookup(args)),
        "PhoneNumber.lookup" => Some(phone_number_lookup(args)),
        "PhoneNumber.resolve_owner" => Some(phone_number_resolve_owner(args)),
        "PhoneNumber.reputation" => Some(phone_number_reputation(args)),
        "PhoneNumber.diff" => Some(phone_number_diff(args)),
        "PhoneNumber.linkage" => Some(phone_number_linkage(args)),
        "PhoneNumber.mitigation" => Some(phone_number_mitigation(args)),
        "PhoneNumber.to_stix" => Some(phone_number_to_stix(args)),
        "PhoneNumber.lrn_carrier" => Some(phone_number_lrn_carrier(args)),
        "PhoneNumber.cnam_name" => Some(phone_number_cnam_name(args)),
        "rdap_lookup" => Some(rdap_lookup(args)),
        "Sources.fanout" => Some(sources_fanout(args)),
        "Sources.list" => Some(sources_list()),
        "DNS.txt" => Some(dns_txt_dispatch(args)),
        "CT.certs" => Some(cert_transparency_lookup(args)),
        _ => None,
    }
}

/// Dispatch method calls on Target/SubdomainResult/TechStack structs.
pub fn dispatch_method(object: &Value, method: &str, args: Vec<Value>) -> Option<StdlibResult> {
    if let Value::Struct { name, .. } = object {
        match name.as_str() {
            "Target" => match method {
                "enumerate_subdomains" => Some(enumerate_subdomains(object, args)),
                "username" => Some(target_username_method(object, args)),
                _ => None,
            },
            "UsernameEnum" => match method {
                "check" => Some(username_enum_check(object, args)),
                _ => None,
            },
            "Phone" => match method {
                "lookup" => Some(phone_lookup(args)),
                _ => None,
            },
            "EmailIntel" => match method {
                "check_spf" => Some(email_intel_check_spf(object)),
                "check_dmarc" => Some(email_intel_check_dmarc(object)),
                "breach_check" => Some(email_intel_breach_check(object)),
                _ => None,
            },
            "IntelGraph" => match method {
                "add_node" => Some(intel_graph_add_node(object, args)),
                "add_edge" => Some(intel_graph_add_edge(object, args)),
                "neighbors" => Some(intel_graph_neighbors(object, args)),
                "nodes" => Some(intel_graph_nodes(object)),
                "edges" => Some(intel_graph_edges(object)),
                "export_stix" => Some(intel_graph_export_stix(object)),
                "export_graphml" => Some(intel_graph_export_graphml(object)),
                "summary" => Some(intel_graph_summary(object)),
                "resolve" => Some(intel_graph_resolve(object, args)),
                _ => None,
            },
            "IncrementalCollector" => match method {
                "register_source" => Some(ic_register_source(object, args)),
                "check_changed" => Some(ic_check_changed(object, args)),
                "record_fetch" => Some(ic_record_fetch(object, args)),
                "watermark" => Some(ic_watermark(object, args)),
                "changed_count" => Some(ic_changed_count(object)),
                _ => None,
            },
            "IntelEntity" | "Finding" => None,
            "IntelReport" => match method {
                "export" => Some(intel_report_export(object, args)),
                "add_finding" => Some(intel_report_add_finding(object, args)),
                _ => None,
            },
            "EnrichmentResult" | "ScanRecord" | "Snapshot"
            | "ScanScope" | "ScanResult" => {
                // Read-only struct types from Plans 03-04
                None
            }
            "SubdomainResult" | "TechStack" | "Technology" | "Provenance"
            | "DomainIntel" | "ASNIntel" | "DocumentMeta"
            | "SpfResult" | "DmarcResult" | "BreachResult" => {
                // Read-only struct types; no instance methods
                None
            }
            _ => None,
        }
    } else {
        None
    }
}

// ══════════════════════════════════════════════════════════════════
// Target constructors (OSINT-01)
// ══════════════════════════════════════════════════════════════════

fn target_domain(args: Vec<Value>) -> StdlibResult {
    let domain = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => return Err("Target.domain() requires a string argument".to_string()),
    };
    Ok(Value::Struct {
        name: "Target".to_string(),
        fields: vec![
            ("kind".to_string(), Value::String("domain".to_string())),
            ("value".to_string(), Value::String(domain)),
            (
                "provenance".to_string(),
                Value::Array(vec![make_provenance("user_input", "Target.domain")]),
            ),
        ],
    })
}

fn target_ip(args: Vec<Value>) -> StdlibResult {
    let ip = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => return Err("Target.ip() requires a string argument".to_string()),
    };
    Ok(Value::Struct {
        name: "Target".to_string(),
        fields: vec![
            ("kind".to_string(), Value::String("ip".to_string())),
            ("value".to_string(), Value::String(ip)),
            (
                "provenance".to_string(),
                Value::Array(vec![make_provenance("user_input", "Target.ip")]),
            ),
        ],
    })
}

fn target_email(args: Vec<Value>) -> StdlibResult {
    let email = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => return Err("Target.email() requires a string argument".to_string()),
    };
    // Email is PII -- wrap in Private
    Ok(Value::Struct {
        name: "Target".to_string(),
        fields: vec![
            ("kind".to_string(), Value::String("email".to_string())),
            (
                "value".to_string(),
                Value::Private(Box::new(Value::String(email))),
            ),
            (
                "provenance".to_string(),
                Value::Array(vec![make_provenance("user_input", "Target.email")]),
            ),
        ],
    })
}

fn target_org(args: Vec<Value>) -> StdlibResult {
    let org = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => return Err("shop-78.example() requires a string argument".to_string()),
    };
    Ok(Value::Struct {
        name: "Target".to_string(),
        fields: vec![
            ("kind".to_string(), Value::String("org".to_string())),
            ("value".to_string(), Value::String(org)),
            (
                "provenance".to_string(),
                Value::Array(vec![make_provenance("user_input", "shop-78.example")]),
            ),
        ],
    })
}

