fn enumerate_subdomains(target: &Value, _args: Vec<Value>) -> StdlibResult {
    let (kind, domain, parent_provenance) = extract_target_fields(target)?;
    if kind != "domain" {
        return Err(format!(
            "enumerate_subdomains requires a domain target, got '{kind}'"
        ));
    }

    let mut results: Vec<Value> = Vec::new();

    // CT log enumeration
    match enumerate_ct_logs(&domain) {
        Ok(subs) => {
            for sub in subs {
                let prov =
                    chain_provenance(&parent_provenance, "crt.sh", "enumerate_subdomains.ct_logs");
                results.push(Value::Struct {
                    name: "SubdomainResult".to_string(),
                    fields: vec![
                        ("subdomain".to_string(), Value::String(sub)),
                        ("source".to_string(), Value::String("ct_logs".to_string())),
                        ("provenance".to_string(), Value::Array(prov)),
                    ],
                });
            }
        }
        Err(e) => {
            // CT log failure is non-fatal; log but continue with DNS brute
            eprintln!("[osint] CT log enumeration failed: {e}");
        }
    }

    // DNS brute-force enumeration
    match enumerate_dns_brute(&domain) {
        Ok(subs) => {
            for sub in subs {
                let prov = chain_provenance(
                    &parent_provenance,
                    "dns_brute",
                    "enumerate_subdomains.dns_brute",
                );
                results.push(Value::Struct {
                    name: "SubdomainResult".to_string(),
                    fields: vec![
                        ("subdomain".to_string(), Value::String(sub)),
                        ("source".to_string(), Value::String("dns_brute".to_string())),
                        ("provenance".to_string(), Value::Array(prov)),
                    ],
                });
            }
        }
        Err(e) => {
            eprintln!("[osint] DNS brute-force failed: {e}");
        }
    }

    Ok(Value::Array(results))
}

/// Extract kind, value, and provenance from a Target struct.
fn extract_target_fields(target: &Value) -> Result<(String, String, Vec<Value>), String> {
    if let Value::Struct { name, fields } = target {
        if name != "Target" {
            return Err(format!("expected Target struct, got '{name}'"));
        }
        let kind = fields
            .iter()
            .find(|(k, _)| k == "kind")
            .map(|(_, v)| v.as_string())
            .unwrap_or_default();
        let value = fields
            .iter()
            .find(|(k, _)| k == "value")
            .map(|(_, v)| match v {
                Value::Private(inner) => inner.as_string(),
                other => other.as_string(),
            })
            .unwrap_or_default();
        let provenance = fields
            .iter()
            .find(|(k, _)| k == "provenance")
            .map(|(_, v)| {
                if let Value::Array(arr) = v {
                    arr.clone()
                } else {
                    vec![]
                }
            })
            .unwrap_or_default();
        Ok((kind, value, provenance))
    } else {
        Err("expected Target struct".to_string())
    }
}

/// Query crt.sh for certificate transparency log entries.
fn enumerate_ct_logs(domain: &str) -> Result<Vec<String>, String> {
    let url = format!("https://crt.sh/?q=%.{domain}&output=json");
    let body = governed_fetch(&url, &[]).map_err(|e| format!("crt.sh request failed: {e}"))?;

    // Parse JSON array, extract name_value fields
    let json: serde_json::Value =
        serde_json::from_str(&body).map_err(|e| format!("crt.sh JSON parse failed: {e}"))?;

    let mut subdomains = HashSet::new();
    if let serde_json::Value::Array(entries) = json {
        for entry in entries {
            if let Some(name_value) = entry.get("name_value").and_then(|v| v.as_str()) {
                // name_value can contain multiple newline-separated domains
                for line in name_value.lines() {
                    let trimmed = line.trim().to_lowercase();
                    if !trimmed.is_empty() && trimmed.ends_with(domain) {
                        subdomains.insert(trimmed);
                    }
                }
            }
        }
    }

    let mut result: Vec<String> = subdomains.into_iter().collect();
    result.sort();
    Ok(result)
}

/// DNS brute-force: resolve common subdomain prefixes against the domain.
fn enumerate_dns_brute(domain: &str) -> Result<Vec<String>, String> {
    // Fail-closed (T-122b): every probe below is a plain-DNS (:53) lookup
    // through the OS resolver — refuse the whole sweep unless the operator
    // opted in (TALLOW_ALLOW_DIRECT); the sanctioned path is DoH.
    crate::runtime::dns_guard::check(53, false)?;
    let mut found = Vec::new();
    for prefix in DNS_BRUTE_WORDLIST {
        let candidate = format!("{prefix}.{domain}");
        // Use std::net::ToSocketAddrs for simple sync DNS lookups
        let addr = format!("{candidate}:80");
        if std::net::ToSocketAddrs::to_socket_addrs(&addr.as_str()).is_ok() {
            found.push(candidate);
        }
    }
    Ok(found)
}

