// ══════════════════════════════════════════════════════════════════

struct TechSignature {
    name: &'static str,
    category: &'static str,
    /// (header_name, pattern_substring) pairs to check in HTTP response headers.
    headers: &'static [(&'static str, &'static str)],
    /// Substrings to search for in the HTML body.
    html_patterns: &'static [&'static str],
    /// Meta generator tag patterns.
    meta_generators: &'static [&'static str],
}

