// WebArchive (OSINT-11, Phase 22, Plan 03)
// ══════════════════════════════════════════════════════════════════

/// WebArchive.snapshots: query Wayback Machine CDX API.
/// Args: (url: String) or (url: String, from: String, to: String)
fn web_archive_snapshots(args: Vec<Value>) -> StdlibResult {
    let target_url = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => {
            return Err(
                "WebArchive.snapshots: first argument must be URL string".to_string(),
            )
        }
    };

    let mut cdx_url = format!(
        "https://web.archive.org/cdx/search/cdx?url={}&output=json&fl=timestamp,original,statuscode,digest",
        target_url.replace(' ', "%20")
    );

    // Optional from/to date filters
    if let Some(Value::String(from)) = args.get(1) {
        cdx_url.push_str(&format!("&from={from}"));
    }
    if let Some(Value::String(to)) = args.get(2) {
        cdx_url.push_str(&format!("&to={to}"));
    }

    let body = governed_fetch(&cdx_url, &[])
        .map_err(|e| format!("WebArchive.snapshots: {e}"))?;

    parse_cdx_response(&body)
}

/// Parse CDX JSON response into array of Snapshot structs.
fn parse_cdx_response(body: &str) -> StdlibResult {
    // CDX returns JSON array of arrays; first row is headers
    let parsed: serde_json::Value = serde_json::from_str(body)
        .map_err(|e| format!("WebArchive.snapshots: JSON parse failed: {e}"))?;

    let rows = match parsed.as_array() {
        Some(arr) => arr,
        None => return Ok(Value::Array(vec![])),
    };

    if rows.is_empty() {
        return Ok(Value::Array(vec![]));
    }

    // Skip first row (headers: ["timestamp","original","statuscode","digest"])
    let data_rows = &rows[1..];

    let snapshots: Vec<Value> = data_rows
        .iter()
        .filter_map(|row| {
            let arr = row.as_array()?;
            let timestamp = arr.first()?.as_str()?.to_string();
            let original_url = arr.get(1)?.as_str()?.to_string();
            let status_code = arr.get(2)?.as_str()?.to_string();
            let digest = arr.get(3)?.as_str()?.to_string();
            let snapshot_url = format!(
                "https://web.archive.org/web/{timestamp}/{original_url}"
            );

            Some(Value::Struct {
                name: "Snapshot".to_string(),
                fields: vec![
                    ("timestamp".to_string(), Value::String(timestamp)),
                    ("original_url".to_string(), Value::String(original_url)),
                    ("status_code".to_string(), Value::String(status_code)),
                    ("digest".to_string(), Value::String(digest)),
                    ("snapshot_url".to_string(), Value::String(snapshot_url)),
                ],
            })
        })
        .collect();

    Ok(Value::Array(snapshots))
}

/// WebArchive.diff: fetch two archive URLs and produce line-by-line diff.
/// Args: (url_a: String, url_b: String)
fn web_archive_diff(args: Vec<Value>) -> StdlibResult {
    let url_a = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => {
            return Err(
                "WebArchive.diff: first argument must be archive URL string".to_string(),
            )
        }
    };

    let url_b = match args.get(1) {
        Some(Value::String(s)) => s.clone(),
        _ => {
            return Err(
                "WebArchive.diff: second argument must be archive URL string".to_string(),
            )
        }
    };

    let body_a = fetch_url_text(&url_a)
        .map_err(|e| format!("WebArchive.diff: failed to fetch first URL: {e}"))?;
    let body_b = fetch_url_text(&url_b)
        .map_err(|e| format!("WebArchive.diff: failed to fetch second URL: {e}"))?;

    Ok(Value::String(simple_line_diff(&body_a, &body_b)))
}

/// Fetch a URL and return body as text.
fn fetch_url_text(url: &str) -> Result<String, String> {
    governed_fetch(url, &[]).map_err(|e| format!("HTTP request failed: {e}"))
}

/// Common Crawl CDX index to query. Indexes rotate periodically; update to the
/// most recent `CC-MAIN-YYYY-WW` when a stale one is retired.
const COMMON_CRAWL_INDEX: &str = "CC-MAIN-2024-51";

/// CommonCrawl.snapshots: query index.commoncrawl.org CDX for historical web
/// captures (free, no key). Mirrors the Wayback CDX pattern to provide
/// multi-source redundancy for the historical-web signal class.
/// Args: (url: String) or (url: String, from: String, to: String)
fn common_crawl_cdx(args: Vec<Value>) -> StdlibResult {
    let target_url = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => {
            return Err(
                "CommonCrawl.snapshots: first argument must be URL string".to_string(),
            )
        }
    };

    // `matchType=prefix` mirrors Wayback's default `url=<url>` match; include
    // filename so we can reconstruct a `data.commoncrawl.org` snapshot URL.
    let mut cdx_url = format!(
        "https://index.commoncrawl.org/{COMMON_CRAWL_INDEX}-index?url={}&output=json&fl=timestamp,url,status,digest,mime,filename&matchType=prefix",
        target_url.replace(' ', "%20")
    );

    if let Some(Value::String(from)) = args.get(1) {
        cdx_url.push_str(&format!("&from={from}"));
    }
    if let Some(Value::String(to)) = args.get(2) {
        cdx_url.push_str(&format!("&to={to}"));
    }

    let body = governed_fetch(&cdx_url, &[])
        .map_err(|e| format!("CommonCrawl.snapshots: {e}"))?;

    // Common Crawl CDX returns NDJSON (one JSON object per line).
    let mut snapshots: Vec<Value> = Vec::new();
    for line in body.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let entry: serde_json::Value = match serde_json::from_str(line) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let timestamp = entry["timestamp"].as_str().unwrap_or("").to_string();
        let original_url = entry["url"].as_str().unwrap_or("").to_string();
        let status_code = entry["status"].as_str().unwrap_or("").to_string();
        let digest = entry["digest"].as_str().unwrap_or("").to_string();
        let filename = entry["filename"].as_str().unwrap_or("").to_string();
        if timestamp.is_empty() || original_url.is_empty() {
            continue;
        }
        let snapshot_url = if filename.is_empty() {
            format!("https://data.commoncrawl.org/{timestamp}/{original_url}")
        } else {
            format!("https://data.commoncrawl.org/{filename}")
        };
        snapshots.push(Value::Struct {
            name: "Snapshot".to_string(),
            fields: vec![
                ("timestamp".to_string(), Value::String(timestamp)),
                ("original_url".to_string(), Value::String(original_url)),
                ("status_code".to_string(), Value::String(status_code)),
                ("digest".to_string(), Value::String(digest)),
                ("snapshot_url".to_string(), Value::String(snapshot_url)),
                ("source".to_string(), Value::String("commoncrawl".to_string())),
            ],
        });
    }

    Ok(Value::Array(snapshots))
}

/// WebArchive.save_page_now: request an on-demand snapshot via the Wayback
/// Save-Page-Now API (`https://web.archive.org/save/<url>`).
/// Args: (url: String)
fn web_archive_save_page_now(args: Vec<Value>) -> StdlibResult {
    let target_url = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => {
            return Err(
                "WebArchive.save_page_now: first argument must be URL string".to_string(),
            )
        }
    };

    let save_url = format!(
        "https://web.archive.org/save/{}",
        target_url.replace(' ', "%20")
    );
    let (status, _body, _retries, rate_limited) = super::http::governed_get(
        &save_url,
        &[("User-Agent".to_string(), "nixe-osint/0.4".to_string())],
        &super::http::GOV_DEFAULT,
        2,
    )
    .map_err(|e| format!("WebArchive.save_page_now: {e}"))?;

    if rate_limited {
        return Err(format!(
            "WebArchive.save_page_now: rate limited (429) for {target_url}"
        ));
    }
    if status == 200 {
        // Capture queued/saved. The resulting snapshot URL follows the
        // standard `web.archive.org/web/<timestamp>/<url>` shape.
        Ok(Value::Struct {
            name: "SavePageNowResult".to_string(),
            fields: vec![
                ("url".to_string(), Value::String(target_url.clone())),
                ("status".to_string(), Value::Int(status as i128)),
                ("saved".to_string(), Value::Bool(true)),
                (
                    "snapshot_url".to_string(),
                    Value::String(format!(
                        "https://web.archive.org/web/2026/{target_url}"
                    )),
                ),
                (
                    "provenance".to_string(),
                    Value::Array(vec![make_provenance(
                        "wayback_spn",
                        "WebArchive.save_page_now",
                    )]),
                ),
            ],
        })
    } else {
        Ok(Value::Struct {
            name: "SavePageNowResult".to_string(),
            fields: vec![
                ("url".to_string(), Value::String(target_url)),
                ("status".to_string(), Value::Int(status as i128)),
                ("saved".to_string(), Value::Bool(false)),
                (
                    "provenance".to_string(),
                    Value::Array(vec![make_provenance(
                        "wayback_spn",
                        "WebArchive.save_page_now",
                    )]),
                ),
            ],
        })
    }
}

/// WebArchive.availability: cheap existence check via the Wayback Availability
/// API (`https://archive.org/wayback/available`). No CDX scan needed.
/// Args: (url: String) or (url: String, timestamp: String)
fn web_archive_availability(args: Vec<Value>) -> StdlibResult {
    let target_url = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => {
            return Err(
                "WebArchive.availability: first argument must be URL string".to_string(),
            )
        }
    };

    let mut avail_url = format!(
        "https://archive.org/wayback/available?url={}",
        target_url.replace(' ', "%20")
    );
    if let Some(Value::String(ts)) = args.get(1) {
        avail_url.push_str(&format!("&timestamp={ts}"));
    }

    let body = governed_fetch(&avail_url, &[])
        .map_err(|e| format!("WebArchive.availability: {e}"))?;

    let parsed: serde_json::Value = serde_json::from_str(&body)
        .map_err(|e| format!("WebArchive.availability: JSON parse failed: {e}"))?;

    let closest = &parsed["archived_snapshots"]["closest"];
    let available = closest["available"].as_bool().unwrap_or(false);
    let snapshot_url = closest["url"].as_str().unwrap_or("").to_string();
    let timestamp = closest["timestamp"].as_str().unwrap_or("").to_string();
    let snapshot_status = closest["status"].as_str().unwrap_or("").to_string();

    Ok(Value::Struct {
        name: "AvailabilityResult".to_string(),
        fields: vec![
            ("url".to_string(), Value::String(target_url)),
            ("available".to_string(), Value::Bool(available)),
            ("snapshot_url".to_string(), Value::String(snapshot_url)),
            ("timestamp".to_string(), Value::String(timestamp)),
            ("snapshot_status".to_string(), Value::String(snapshot_status)),
            (
                "provenance".to_string(),
                Value::Array(vec![make_provenance(
                    "wayback_availability",
                    "WebArchive.availability",
                )]),
            ),
        ],
    })
}

/// Simple line-by-line diff between two texts.
/// Output format: lines prefixed with ' ' (same), '-' (removed), '+' (added).
fn simple_line_diff(text_a: &str, text_b: &str) -> String {
    let lines_a: Vec<&str> = text_a.lines().collect();
    let lines_b: Vec<&str> = text_b.lines().collect();

    let mut output = String::new();
    let max_len = lines_a.len().max(lines_b.len());

    // Simple longest-common-subsequence approach is expensive;
    // use a practical line-by-line comparison instead.
    let mut i = 0;
    let mut j = 0;

    while i < lines_a.len() && j < lines_b.len() {
        if lines_a[i] == lines_b[j] {
            output.push_str(&format!(" {}\n", lines_a[i]));
            i += 1;
            j += 1;
        } else {
            // Look ahead to find if line from A appears later in B (added lines)
            // or if line from B appears later in A (removed lines)
            let look_ahead = 5.min(max_len - i.max(j));
            let mut found_a_in_b = None;
            let mut found_b_in_a = None;

            for k in 1..=look_ahead {
                if found_a_in_b.is_none() && j + k < lines_b.len() && lines_a[i] == lines_b[j + k]
                {
                    found_a_in_b = Some(k);
                }
                if found_b_in_a.is_none() && i + k < lines_a.len() && lines_b[j] == lines_a[i + k]
                {
                    found_b_in_a = Some(k);
                }
            }

            match (found_a_in_b, found_b_in_a) {
                (Some(kb), _) if kb <= found_b_in_a.unwrap_or(usize::MAX) => {
                    // Lines were added in B
                    for _ in 0..kb {
                        output.push_str(&format!("+{}\n", lines_b[j]));
                        j += 1;
                    }
                }
                (_, Some(ka)) => {
                    // Lines were removed from A
                    for _ in 0..ka {
                        output.push_str(&format!("-{}\n", lines_a[i]));
                        i += 1;
                    }
                }
                _ => {
                    // Changed line
                    output.push_str(&format!("-{}\n", lines_a[i]));
                    output.push_str(&format!("+{}\n", lines_b[j]));
                    i += 1;
                    j += 1;
                }
            }
        }
    }

    // Remaining lines
    while i < lines_a.len() {
        output.push_str(&format!("-{}\n", lines_a[i]));
        i += 1;
    }
    while j < lines_b.len() {
        output.push_str(&format!("+{}\n", lines_b[j]));
        j += 1;
    }

    output
}

// ══════════════════════════════════════════════════════════════════
// Username enumeration (OSINT-01) — sherlock/Maigret/WhatsMyName-style
// ══════════════════════════════════════════════════════════════════
//
// The HTTP-probe engine below checks a single handle across a curated
// database of site-matching patterns. Each pattern records the site's
// profile URL shape, the HTTP status codes that indicate a real account,
// and body substrings that indicate "user not found" (some sites return
// 200 with an error body instead of a 404).
//
// NOTE (stealth): for hard targets (Cloudflare-protected, bot-detection,
// or login-walled sites), the HTTP probe can yield false negatives. Run
// UsernameEnum.check through Tallow's stealth browser (browser module)
// for those sites instead. The HTTP probe version is the default here.

/// A single site-matching pattern (WhatsMyName-style).
struct UsernamePattern {
    name: &'static str,
    category: &'static str,
    /// URL template with a `{handle}` placeholder.
    base_url: &'static str,
    /// HTTP status codes that indicate the profile exists.
    ok_statuses: &'static [i32],
    /// Body substrings that, if present, indicate the account does NOT exist.
    not_found_markers: &'static [&'static str],
}

