/// Construct a `UsernameEnum` struct from a handle string.
fn make_username_enum(handle: &str, hits: Vec<Value>) -> Value {
    let found_count = hits
        .iter()
        .filter(|h| {
            if let Value::Struct { fields, .. } = h {
                fields
                    .iter()
                    .any(|(k, v)| k == "found" && matches!(v, Value::Bool(true)))
            } else {
                false
            }
        })
        .count();
    Value::Struct {
        name: "UsernameEnum".to_string(),
        fields: vec![
            ("handle".to_string(), Value::String(handle.to_string())),
            ("hits".to_string(), Value::Array(hits)),
            ("found_count".to_string(), Value::Int(found_count as i128)),
            (
                "checked_at".to_string(),
                Value::String(chrono::Utc::now().to_rfc3339()),
            ),
            (
                "provenance".to_string(),
                Value::Array(vec![make_provenance(
                    "username_enum",
                    "UsernameEnum.check",
                )]),
            ),
        ],
    }
}

/// Extract the handle string from a UsernameEnum struct.
fn extract_username_handle(object: &Value) -> Result<String, String> {
    if let Value::Struct { name, fields } = object {
        if name != "UsernameEnum" {
            return Err(format!("expected UsernameEnum struct, got '{name}'"));
        }
        fields
            .iter()
            .find(|(k, _)| k == "handle")
            .map(|(_, v)| v.as_string())
            .ok_or_else(|| "UsernameEnum missing handle field".to_string())
    } else {
        Err("expected UsernameEnum struct".to_string())
    }
}

/// Extract the handle string from a Target struct value (unwrapping Private).
fn extract_target_username(object: &Value) -> Result<String, String> {
    let (kind, value, _) = extract_target_fields(object)?;
    if kind != "username" {
        return Err(format!(
            "username enumeration requires a username target, got '{kind}'"
        ));
    }
    Ok(value)
}

/// Build the profile URL for a pattern, substituting {handle}.
fn build_profile_url(pattern: &UsernamePattern, handle: &str) -> String {
    pattern.base_url.replace("{handle}", handle)
}

/// Probe a single site pattern for a handle. Returns (site_name, found, url).
fn probe_username_site(pattern: &UsernamePattern, handle: &str) -> (String, bool, String) {
    let url = build_profile_url(pattern, handle);
    // Egress: honour TALLOW_PROXY/TALLOW_TOR (was a direct agent).
    let agent = crate::runtime::egress_http::agent_with_timeouts(
        Some(std::time::Duration::from_secs(12)),
        None,
    );

    let resp = match agent.get(&url).call() {
        Ok(r) => r,
        Err(e) => {
            // Network / TLS failure → site unreachable, treat as not found (no signal)
            eprintln!("[osint] username probe {url}: {e}");
            return (pattern.name.to_string(), false, url);
        }
    };
    let status = resp.status();
    let body = resp
        .into_body()
        .read_to_string()
        .unwrap_or_default()
        .to_lowercase();

    let status_ok = pattern
        .ok_statuses
        .contains(&(status.as_u16() as i32));
    if !status_ok {
        return (pattern.name.to_string(), false, url);
    }
    // Status OK but body may still say "user not found".
    let has_marker = pattern
        .not_found_markers
        .iter()
        .any(|m| body.contains(&m.to_lowercase()));
    (pattern.name.to_string(), !has_marker, url)
}

/// HTTP-probe engine: check a handle against every curated pattern.
/// `limit` = max sites to probe (0 = all); `delay_ms` = politeness sleep
/// between probes (rate-limit aware).
fn check_username_http(handle: &str, limit: usize, delay_ms: u64) -> Vec<Value> {
    let mut hits = Vec::new();
    let total = if limit == 0 {
        USERNAME_PATTERNS.len()
    } else {
        limit.min(USERNAME_PATTERNS.len())
    };

    for pattern in &USERNAME_PATTERNS[..total] {
        let (name, found, url) = probe_username_site(pattern, handle);
        hits.push(Value::Struct {
            name: "UsernameHit".to_string(),
            fields: vec![
                ("site".to_string(), Value::String(name)),
                (
                    "category".to_string(),
                    Value::String(pattern.category.to_string()),
                ),
                ("url".to_string(), Value::String(url)),
                ("found".to_string(), Value::Bool(found)),
            ],
        });
        if delay_ms > 0 {
            std::thread::sleep(std::time::Duration::from_millis(delay_ms));
        }
    }
    hits
}

/// `UsernameEnum.new(handle)` — build a UsernameEnum for a handle.
fn username_enum_new(args: Vec<Value>) -> StdlibResult {
    let handle = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => return Err("UsernameEnum.new() requires a handle string argument".to_string()),
    };
    Ok(make_username_enum(&handle, Vec::new()))
}

/// `UsernameEnum.check(handle [, limit [, delay_ms]])` — static check.
fn username_enum_check_handle(args: Vec<Value>) -> StdlibResult {
    let handle = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => return Err("UsernameEnum.check() requires a handle string argument".to_string()),
    };
    let limit = match args.get(1) {
        Some(Value::Int(n)) if *n > 0 => *n as usize,
        _ => 0,
    };
    let delay_ms = match args.get(2) {
        Some(Value::Int(n)) if *n > 0 => *n as u64,
        _ => 150,
    };
    let hits = check_username_http(&handle, limit, delay_ms);
    Ok(make_username_enum(&handle, hits))
}

/// `Target.username` static — build a UsernameEnum from a handle string.
fn target_username(args: Vec<Value>) -> StdlibResult {
    let handle = match args.first() {
        Some(Value::String(s)) => s.clone(),
        _ => return Err("Target.username() requires a handle string argument".to_string()),
    };
    Ok(make_username_enum(&handle, Vec::new()))
}

/// `Target.username` method — build a UsernameEnum from a Target(username) value.
fn target_username_method(object: &Value, _args: Vec<Value>) -> StdlibResult {
    let handle = extract_target_username(object)?;
    Ok(make_username_enum(&handle, Vec::new()))
}

/// `UsernameEnum.check([limit [, delay_ms]])` method on an existing UsernameEnum.
fn username_enum_check(object: &Value, args: Vec<Value>) -> StdlibResult {
    let handle = extract_username_handle(object)?;
    let limit = match args.first() {
        Some(Value::Int(n)) if *n > 0 => *n as usize,
        _ => 0,
    };
    let delay_ms = match args.get(1) {
        Some(Value::Int(n)) if *n > 0 => *n as u64,
        _ => 150,
    };
    let hits = check_username_http(&handle, limit, delay_ms);
    Ok(make_username_enum(&handle, hits))
}

