    // ── WHOIS parsing tests (OSINT-04) ──

    #[test]
    fn test_domain_intel_whois_parse() {
        let sample_whois = r#"
   Domain Name: EXAMPLE.COM
   Registry Domain ID: 2336799_DOMAIN_COM-VRSN
   Registrar WHOIS Server: whois.iana.org
   Registrar URL: http://www.iana.org
   Updated Date: 2024-08-14T07:01:38Z
   Creation Date: 1995-08-14T04:00:00Z
   Registry Expiry Date: 2025-08-13T04:00:00Z
   Registrar: RESERVED-Internet Assigned Numbers Authority
   Domain Status: clientDeleteProhibited
   Domain Status: clientTransferProhibited
   Domain Status: clientUpdateProhibited
   Name Server: A.IANA-SERVERS.NET
   Name Server: B.IANA-SERVERS.NET
"#;
        let fields = parse_whois_fields(sample_whois);

        // Check registrar
        let registrar = fields.iter().find(|(k, _)| k == "registrar");
        assert!(registrar.is_some(), "should extract registrar");
        if let Some((_, Value::String(v))) = registrar {
            assert!(
                v.contains("RESERVED"),
                "registrar should contain RESERVED, got: {v}"
            );
        }

        // Check creation date
        let created = fields.iter().find(|(k, _)| k == "creation_date");
        assert!(created.is_some(), "should extract creation_date");
        if let Some((_, Value::String(v))) = created {
            assert!(v.contains("1995"), "creation date should contain 1995, got: {v}");
        }

        // Check expiration date
        let expires = fields.iter().find(|(k, _)| k == "expiration_date");
        assert!(expires.is_some(), "should extract expiration_date");

        // Check nameservers
        let ns = fields.iter().find(|(k, _)| k == "nameservers");
        assert!(ns.is_some(), "should extract nameservers");
        if let Some((_, Value::Array(arr))) = ns {
            assert_eq!(arr.len(), 2, "should have 2 nameservers");
            assert!(matches!(&arr[0], Value::String(s) if s.contains("iana-servers")));
        }

        // Check status
        let status = fields.iter().find(|(k, _)| k == "status");
        assert!(status.is_some(), "should extract status");
        if let Some((_, Value::Array(arr))) = status {
            assert!(arr.len() >= 3, "should have at least 3 status values, got {}", arr.len());
        }
    }

    #[test]
    fn test_asn_intel_parse() {
        let sample_arin = r#"
NetRange:       8.8.8.0 - 8.8.8.255
CIDR:           8.8.8.0/24
NetName:        LVLT-GOGL-8-8-8
NetHandle:      NET-8-8-8-0-2
OrgName:        Google LLC
OrgId:          GOGL
Country:        US
OriginAS:       AS15169
"#;
        let fields = parse_asn_fields(sample_arin);

        let asn = fields.iter().find(|(k, _)| k == "asn_number");
        assert!(asn.is_some(), "should extract ASN number");
        if let Some((_, Value::String(v))) = asn {
            assert!(v.contains("15169"), "ASN should contain 15169, got: {v}");
        }

        let org = fields.iter().find(|(k, _)| k == "org_name");
        assert!(org.is_some(), "should extract org name");
        if let Some((_, Value::String(v))) = org {
            assert!(v.contains("Google"), "org should contain Google, got: {v}");
        }

        let country = fields.iter().find(|(k, _)| k == "country");
        assert!(country.is_some(), "should extract country");
        if let Some((_, Value::String(v))) = country {
            assert_eq!(v, "US");
        }

        let net = fields.iter().find(|(k, _)| k == "network_range");
        assert!(net.is_some(), "should extract network range");
        if let Some((_, Value::String(v))) = net {
            assert!(v.contains("8.8.8"), "network range should contain 8.8.8, got: {v}");
        }
    }

    // ── SPF/DMARC parsing tests (OSINT-05) ──

    #[test]
    fn test_email_intel_spf_parse() {
        let spf = "v=spf1 ip4:192.168.0.0/16 include:_spf.google.com include:spf.protection.outlook.com -all";
        let (mechanisms, all_q, includes) = parse_spf_mechanisms(spf);

        assert!(!mechanisms.is_empty(), "should have mechanisms");
        assert_eq!(all_q, "-", "all qualifier should be hard fail (-)");
        assert_eq!(includes.len(), 2, "should have 2 includes");
        assert!(matches!(&includes[0], Value::String(s) if s == "_spf.google.com"));
        assert!(matches!(&includes[1], Value::String(s) if s.contains("outlook.com")));

        // Check ip4 mechanism is present
        let has_ip4 = mechanisms.iter().any(|m| {
            matches!(m, Value::String(s) if s.starts_with("ip4:"))
        });
        assert!(has_ip4, "should have ip4 mechanism");
    }

    #[test]
    fn test_email_intel_spf_parse_softfail() {
        let spf = "v=spf1 include:example.com ~all";
        let (_, all_q, includes) = parse_spf_mechanisms(spf);
        assert_eq!(all_q, "~", "all qualifier should be softfail (~)");
        assert_eq!(includes.len(), 1);
    }

    #[test]
    fn test_email_intel_spf_parse_redirect() {
        let spf = "v=spf1 redirect=_spf.example.com";
        let (mechanisms, _, includes) = parse_spf_mechanisms(spf);
        assert!(!mechanisms.is_empty());
        assert_eq!(includes.len(), 1, "redirect should be counted as include");
        assert!(matches!(&includes[0], Value::String(s) if s.starts_with("redirect:")));
    }

    #[test]
    fn test_email_intel_dmarc_parse() {
        let dmarc = "v=DMARC1; p=reject; rua=mailto:dmarc@example.com; pct=100; adkim=s; aspf=s";
        let fields = parse_dmarc_tags(dmarc);

        let policy = fields.iter().find(|(k, _)| k == "policy");
        assert!(policy.is_some(), "should extract policy");
        if let Some((_, Value::String(v))) = policy {
            assert_eq!(v, "reject");
        }

        let rua = fields.iter().find(|(k, _)| k == "rua");
        assert!(rua.is_some(), "should extract rua");
        if let Some((_, Value::String(v))) = rua {
            assert!(v.contains("mailto:"), "rua should contain mailto, got: {v}");
        }

        let pct = fields.iter().find(|(k, _)| k == "pct");
        assert!(pct.is_some(), "should extract pct");

        let adkim = fields.iter().find(|(k, _)| k == "adkim");
        assert!(adkim.is_some(), "should extract adkim");
        if let Some((_, Value::String(v))) = adkim {
            assert_eq!(v, "s");
        }
    }

