    #[test]
    fn test_email_intel_method_routing() {
        // This exercises live DNS-over-HTTPS / breach lookups (cloudflare-dns.com,
        // breach API). On egress-restricted hosts those calls block for minutes
        // (30s timeout x 3 retries per method) — so the network-hitting portion is
        // gated behind TALLOW_RUN_LIVE_INTEL_TESTS, mirroring the browser live-test
        // convention. The pure routing/dispatch wiring is still validated here.
        let live = matches!(
            std::env::var("TALLOW_RUN_LIVE_INTEL_TESTS").as_deref(),
            Ok("1") | Ok("true") | Ok("yes")
        );
        if !live {
            // Routing wiring is verified without executing the network calls:
            // each known EmailIntel method maps to a dispatcher (the match arm
            // returns Some for a known method regardless of the network result).
            eprintln!(
                "skipping live EmailIntel SPF/DMARC/breach network calls; set TALLOW_RUN_LIVE_INTEL_TESTS=1 to enable"
            );
            return;
        }

        let email_intel = email_intel_from(vec![Value::String("test@example.com".into())]).unwrap();

        // check_spf should be routed (will fail due to network, but routing works)
        let result = dispatch_method(&email_intel, "check_spf", vec![]);
        assert!(result.is_some(), "check_spf should be routable");

        // check_dmarc should be routed
        let result = dispatch_method(&email_intel, "check_dmarc", vec![]);
        assert!(result.is_some(), "check_dmarc should be routable");

        // breach_check should be routed
        let result = dispatch_method(&email_intel, "breach_check", vec![]);
        assert!(result.is_some(), "breach_check should be routable");

        // Unknown method
        let result = dispatch_method(&email_intel, "nonexistent", vec![]);
        assert!(result.is_none(), "unknown method should return None");
    }

