    #[test]
    fn test_document_meta_pdf() {
        // Minimal PDF with Info dictionary containing Title and Author
        // This is a valid minimal PDF structure
        let pdf_bytes = b"%PDF-1.4\n1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n2 0 obj\n<< /Type /Pages /Kids [] /Count 0 >>\nendobj\n3 0 obj\n<< /Title (Test Document) /Author (John Doe) /Creator (TallowTest) >>\nendobj\nxref\n0 4\n0000000000 65535 f \n0000000009 00000 n \n0000000058 00000 n \n0000000115 00000 n \ntrailer\n<< /Size 4 /Root 1 0 R /Info 3 0 R >>\nstartxref\n210\n%%EOF";

        let result = parse_document(vec![Value::Array(
            pdf_bytes.iter().map(|b| Value::Int(*b as i128)).collect(),
        )]);

        // PDF parsing may fail on minimal test bytes, but format detection should work
        match result {
            Ok(Value::Struct { name, fields }) => {
                assert_eq!(name, "DocumentMeta");
                let format = fields.iter().find(|(k, _)| k == "format");
                assert!(format.is_some(), "should have format field");
                if let Some((_, Value::String(f))) = format {
                    assert_eq!(f, "PDF");
                }
                // If author was extracted, it should be Private
                if let Some((_, author_val)) = fields.iter().find(|(k, _)| k == "author") {
                    assert!(
                        matches!(author_val, Value::Private(_)),
                        "author should be Private-wrapped"
                    );
                }
            }
            Err(e) => {
                // Minimal PDF may not parse with lopdf, that's OK --
                // verify it was at least detected as PDF (error should mention PDF)
                assert!(
                    e.contains("PDF"),
                    "error should mention PDF format, got: {e}"
                );
            }
            _ => panic!("unexpected result type"),
        }
    }

    #[test]
    fn test_document_meta_format_detection() {
        // PDF magic
        let pdf = vec![Value::Int(0x25), Value::Int(0x50), Value::Int(0x44), Value::Int(0x46), Value::Int(0x2D)]; // %PDF-
        let result = parse_document(vec![Value::Array(pdf)]);
        // Should attempt PDF parsing (may fail on truncated data, but detects format)
        assert!(result.is_err() || matches!(result, Ok(Value::Struct { .. })));

        // JPEG magic
        let jpeg = vec![Value::Int(0xFF), Value::Int(0xD8), Value::Int(0xFF), Value::Int(0xE1), Value::Int(0x00)];
        let result = parse_document(vec![Value::Array(jpeg)]);
        // Should attempt EXIF parsing
        assert!(result.is_err() || matches!(result, Ok(Value::Struct { .. })));

        // ZIP/OOXML magic
        let zip_magic = vec![Value::Int(0x50), Value::Int(0x4B), Value::Int(0x03), Value::Int(0x04), Value::Int(0x14)];
        let result = parse_document(vec![Value::Array(zip_magic)]);
        // Should attempt ZIP/OOXML parsing
        assert!(result.is_err() || matches!(result, Ok(Value::Struct { .. })));

        // OLE2 magic (old Office)
        let ole2 = vec![Value::Int(0xD0), Value::Int(0xCF), Value::Int(0x11), Value::Int(0xE0)];
        let result = parse_document(vec![Value::Array(ole2)]);
        assert!(result.is_err(), "OLE2 should return unsupported error");
        assert!(result.unwrap_err().contains("unsupported format"), "should mention unsupported");

        // Unknown format
        let unknown = vec![Value::Int(0x00), Value::Int(0x00), Value::Int(0x00), Value::Int(0x00)];
        let result = parse_document(vec![Value::Array(unknown)]);
        assert!(result.is_err(), "unknown format should return error");

        // Too short
        let short = vec![Value::Int(0x00), Value::Int(0x00)];
        let result = parse_document(vec![Value::Array(short)]);
        assert!(result.is_err(), "too short input should return error");
    }

