    /// The egress contract has no silent fallback, so a WHOIS lookup must ride a
    /// configured proxy and must NOT fall back to a direct port-43 connect. A
    /// deliberately dead proxy proves which path ran without touching the network:
    /// the failure names the proxy, and never the direct "connect to <server> failed".
    #[test]
    fn whois_rides_the_configured_egress_contract() {
        let _guard = crate::runtime::egress_http::env_lock();
        let saved = std::env::var("TALLOW_PROXY").ok();
        let saved_direct = std::env::var("TALLOW_ALLOW_DIRECT").ok();
        // Discard port: nothing listens there, so the connect fails immediately.
        unsafe { std::env::set_var("TALLOW_PROXY", "socks5h://127.0.0.1:9") };
        let result = whois_stream("whois.arin.net");
        unsafe {
            match saved {
                Some(v) => std::env::set_var("TALLOW_PROXY", v),
                None => std::env::remove_var("TALLOW_PROXY"),
            }
            match saved_direct {
                Some(v) => std::env::set_var("TALLOW_ALLOW_DIRECT", v),
                None => std::env::remove_var("TALLOW_ALLOW_DIRECT"),
            }
        }
        let err = result.expect_err("a dead proxy must not yield a stream");
        assert!(
            err.contains("via socks5h://127.0.0.1:9"),
            "the lookup must ride the configured proxy; got: {err}"
        );
        assert!(
            !err.contains("WHOIS connect to whois.arin.net failed"),
            "a direct port-43 connect would bypass the egress contract; got: {err}"
        );
    }

    #[test]
    fn whois_direct_only_when_the_contract_declares_it_deliberate() {
        let _guard = crate::runtime::egress_http::env_lock();
        let saved = std::env::var("TALLOW_PROXY").ok();
        let saved_direct = std::env::var("TALLOW_ALLOW_DIRECT").ok();
        unsafe {
            std::env::remove_var("TALLOW_PROXY");
            std::env::set_var("TALLOW_ALLOW_DIRECT", "1");
        }
        // No proxy asked for, so the contract says direct is deliberate: the attempt must
        // be a direct connect, never a SOCKS5 route. Loopback (nothing listens on :43
        // there) keeps this offline and instant - the assertion is about which path was
        // taken, and a test for "never egress directly" must not itself egress.
        let err = whois_stream("127.0.0.1").expect_err("nothing is listening on 127.0.0.1:43");
        unsafe {
            match saved {
                Some(v) => std::env::set_var("TALLOW_PROXY", v),
                None => std::env::remove_var("TALLOW_PROXY"),
            }
            match saved_direct {
                Some(v) => std::env::set_var("TALLOW_ALLOW_DIRECT", v),
                None => std::env::remove_var("TALLOW_ALLOW_DIRECT"),
            }
        }
        assert!(
            !err.contains("via socks5h://"),
            "TALLOW_ALLOW_DIRECT means direct was asked for; got: {err}"
        );
        assert!(
            err.contains("WHOIS connect to 127.0.0.1 failed"),
            "the deliberate-direct case must connect directly; got: {err}"
        );
    }

