    /// Helper to extract a string field from a Value::Struct.
    fn get_str_field<'a>(fields: &'a [(String, Value)], key: &str) -> Option<&'a str> {
        fields.iter().find(|(k, _)| k == key).and_then(|(_, v)| {
            if let Value::String(s) = v {
                Some(s.as_str())
            } else {
                None
            }
        })
    }

    /// Helper to extract an int field from a Value::Struct.
    fn get_int_field(fields: &[(String, Value)], key: &str) -> Option<i128> {
        fields.iter().find(|(k, _)| k == key).and_then(|(_, v)| {
            if let Value::Int(n) = v {
                Some(*n)
            } else {
                None
            }
        })
    }

