    fn test_web_archive_snapshots_parse_cdx_response() {
        // Mock CDX API JSON response (first row is headers)
        let cdx_json = r#"[
            ["timestamp","original","statuscode","digest"],
            ["20230101120000","http://example.com","200","ABC123"],
            ["20230615080000","http://example.com","200","DEF456"]
        ]"#;

        let result = parse_cdx_response(cdx_json);
        assert!(result.is_ok(), "parse should succeed: {:?}", result);

        if let Ok(Value::Array(snapshots)) = &result {
            assert_eq!(snapshots.len(), 2, "should have 2 data rows");

            // Check first snapshot
            if let Value::Struct { name, fields } = &snapshots[0] {
                assert_eq!(name, "Snapshot");
                assert_eq!(get_str_field(fields, "timestamp"), Some("20230101120000"));
                assert_eq!(get_str_field(fields, "original_url"), Some("http://example.com"));
                assert_eq!(get_str_field(fields, "status_code"), Some("200"));
                assert_eq!(get_str_field(fields, "digest"), Some("ABC123"));
                assert_eq!(
                    get_str_field(fields, "snapshot_url"),
                    Some("https://web.archive.org/web/20230101120000/http://example.com")
                );
            } else {
                panic!("expected Snapshot struct");
            }

            // Check second snapshot
            if let Value::Struct { name, fields } = &snapshots[1] {
                assert_eq!(name, "Snapshot");
                assert_eq!(get_str_field(fields, "timestamp"), Some("20230615080000"));
                assert_eq!(get_str_field(fields, "digest"), Some("DEF456"));
            } else {
                panic!("expected Snapshot struct");
            }
        } else {
            panic!("expected Value::Array");
        }
    }

