    #[test]
    fn test_web_archive_diff_simple() {
        let text_a = "line 1\nline 2\nline 3\n";
        let text_b = "line 1\nline modified\nline 3\n";
        let diff = simple_line_diff(text_a, text_b);
        assert!(diff.contains(" line 1"), "should have unchanged line 1");
        assert!(diff.contains("-line 2"), "should show removed line 2");
        assert!(diff.contains("+line modified"), "should show added line");
        assert!(diff.contains(" line 3"), "should have unchanged line 3");
    }

    #[test]
    fn test_web_archive_diff_added_lines() {
        let text_a = "line 1\nline 3\n";
        let text_b = "line 1\nline 2\nline 3\n";
        let diff = simple_line_diff(text_a, text_b);
        assert!(diff.contains("+line 2"), "should show added line 2");
        assert!(diff.contains(" line 1"), "line 1 unchanged");
        assert!(diff.contains(" line 3"), "line 3 unchanged");
    }

