    #[test]
    fn test_web_archive_snapshots_date_range_filter() {
        // Test that from/to args are accepted without arg parsing errors.
        // CDX API is public so this may succeed or fail depending on network.
        let result = web_archive_snapshots(vec![
            Value::String("http://example.com".into()),
            Value::String("20230101".into()),
            Value::String("20231231".into()),
        ]);
        match &result {
            Ok(Value::Array(snapshots)) => {
                // Network succeeded -- verify results are Snapshot structs
                for snap in snapshots {
                    if let Value::Struct { name, .. } = snap {
                        assert_eq!(name, "Snapshot");
                    } else {
                        panic!("expected Snapshot struct in array");
                    }
                }
            }
            Err(e) => {
                // Network failed -- should be a network error, not arg error
                assert!(
                    e.contains("request failed") || e.contains("WebArchive"),
                    "should be network error, not arg error: {e}"
                );
            }
            _ => panic!("expected Array or Err"),
        }
    }

