    #[test]
    fn test_intel_graph_new() {
        let result = dispatch("IntelGraph.new", vec![]);
        assert!(result.is_some(), "IntelGraph.new should be routable");
        let graph = result.unwrap().unwrap();
        if let Value::Struct { name, fields } = &graph {
            assert_eq!(name, "IntelGraph");
            let nodes = fields.iter().find(|(k, _)| k == "nodes");
            assert!(nodes.is_some(), "should have nodes field");
            if let Some((_, Value::Array(n))) = nodes {
                assert!(n.is_empty(), "nodes should be empty initially");
            } else {
                panic!("nodes should be an Array");
            }
            let edges = fields.iter().find(|(k, _)| k == "edges");
            assert!(edges.is_some(), "should have edges field");
            if let Some((_, Value::Array(e))) = edges {
                assert!(e.is_empty(), "edges should be empty initially");
            } else {
                panic!("edges should be an Array");
            }
        } else {
            panic!("expected IntelGraph struct");
        }
    }

    #[test]
    fn test_intel_graph_add_node_valid() {
        let graph = dispatch("IntelGraph.new", vec![]).unwrap().unwrap();
        let result = dispatch_method(
            &graph,
            "add_node",
            vec![
                Value::String("indicator".into()),
                Value::String("evil.com".into()),
                Value::String("B".into()),
                Value::Int(2),
                Value::Map(vec![]),
            ],
        );
        assert!(result.is_some(), "add_node should be routable");
        let updated = result.unwrap().unwrap();
        if let Value::Struct { name, fields } = &updated {
            assert_eq!(name, "IntelGraph");
            let nodes = fields.iter().find(|(k, _)| k == "nodes");
            if let Some((_, Value::Array(n))) = nodes {
                assert_eq!(n.len(), 1, "should have one node");
                if let Value::Struct {
                    name: en,
                    fields: ef,
                } = &n[0]
                {
                    assert_eq!(en, "IntelEntity");
                    let id_field = ef.iter().find(|(k, _)| k == "id");
                    assert!(id_field.is_some());
                    if let Some((_, Value::String(id))) = id_field {
                        assert!(
                            id.starts_with("indicator--"),
                            "STIX ID should start with type--: {id}"
                        );
                    }
                    let rel = ef.iter().find(|(k, _)| k == "reliability");
                    assert!(matches!(rel, Some((_, Value::String(s))) if s == "B"));
                    let cred = ef.iter().find(|(k, _)| k == "credibility");
                    assert!(matches!(cred, Some((_, Value::Int(2)))));
                }
            } else {
                panic!("expected nodes array");
            }
        }
    }

