    #[test]
    fn test_intel_graph_add_edge() {
        let graph = dispatch("IntelGraph.new", vec![]).unwrap().unwrap();
        // Add two nodes first
        let graph = dispatch_method(
            &graph,
            "add_node",
            vec![
                Value::String("indicator".into()),
                Value::String("evil.com".into()),
                Value::String("B".into()),
                Value::Int(2),
                Value::Map(vec![]),
            ],
        )
        .unwrap()
        .unwrap();
        let graph = dispatch_method(
            &graph,
            "add_node",
            vec![
                Value::String("threat-actor".into()),
                Value::String("APT28".into()),
                Value::String("C".into()),
                Value::Int(3),
                Value::Map(vec![]),
            ],
        )
        .unwrap()
        .unwrap();

        // Get node IDs
        let nodes_val = dispatch_method(&graph, "nodes", vec![]).unwrap().unwrap();
        let node_ids: Vec<String> = if let Value::Array(nodes) = &nodes_val {
            nodes
                .iter()
                .filter_map(|n| {
                    if let Value::Struct { fields, .. } = n {
                        fields
                            .iter()
                            .find(|(k, _)| k == "id")
                            .and_then(|(_, v)| if let Value::String(s) = v { Some(s.clone()) } else { None })
                    } else {
                        None
                    }
                })
                .collect()
        } else {
            panic!("expected array");
        };

        let result = dispatch_method(
            &graph,
            "add_edge",
            vec![
                Value::String(node_ids[0].clone()),
                Value::String(node_ids[1].clone()),
                Value::String("indicates".into()),
            ],
        );
        assert!(result.is_some());
        let updated = result.unwrap().unwrap();
        if let Value::Struct { fields, .. } = &updated {
            let edges = fields.iter().find(|(k, _)| k == "edges");
            if let Some((_, Value::Array(e))) = edges {
                assert_eq!(e.len(), 1, "should have one edge");
            }
        }
    }

    #[test]
    fn test_intel_graph_neighbors() {
        let graph = dispatch("IntelGraph.new", vec![]).unwrap().unwrap();
        let graph = dispatch_method(
            &graph,
            "add_node",
            vec![
                Value::String("indicator".into()),
                Value::String("evil.com".into()),
                Value::String("A".into()),
                Value::Int(1),
                Value::Map(vec![]),
            ],
        )
        .unwrap()
        .unwrap();
        let graph = dispatch_method(
            &graph,
            "add_node",
            vec![
                Value::String("threat-actor".into()),
                Value::String("APT28".into()),
                Value::String("B".into()),
                Value::Int(2),
                Value::Map(vec![]),
            ],
        )
        .unwrap()
        .unwrap();

        // Get IDs
        let nodes_val = dispatch_method(&graph, "nodes", vec![]).unwrap().unwrap();
        let node_ids: Vec<String> = if let Value::Array(nodes) = &nodes_val {
            nodes
                .iter()
                .filter_map(|n| {
                    if let Value::Struct { fields, .. } = n {
                        fields
                            .iter()
                            .find(|(k, _)| k == "id")
                            .and_then(|(_, v)| if let Value::String(s) = v { Some(s.clone()) } else { None })
                    } else {
                        None
                    }
                })
                .collect()
        } else {
            panic!("expected array");
        };

        let graph = dispatch_method(
            &graph,
            "add_edge",
            vec![
                Value::String(node_ids[0].clone()),
                Value::String(node_ids[1].clone()),
                Value::String("indicates".into()),
            ],
        )
        .unwrap()
        .unwrap();

        // neighbors of first node should include second
        let neighbors = dispatch_method(
            &graph,
            "neighbors",
            vec![Value::String(node_ids[0].clone())],
        )
        .unwrap()
        .unwrap();
        if let Value::Array(n) = &neighbors {
            assert!(!n.is_empty(), "should have at least one neighbor");
            // Should contain the second node's ID
            let has_second = n.iter().any(|v| matches!(v, Value::String(s) if s == &node_ids[1]));
            assert!(has_second, "neighbors should contain the connected node");
        } else {
            panic!("expected array from neighbors()");
        }
    }

