    #[test]
    fn test_stix_export_admiralty_confidence_mapping() {
        // A1 = 100*1.0 = 100
        assert_eq!(admiralty_to_confidence("A", 1), 100);
        // B2 = 80*0.8 = 64
        assert_eq!(admiralty_to_confidence("B", 2), 64);
        // C3 = 60*0.6 = 36
        assert_eq!(admiralty_to_confidence("C", 3), 36);
        // D4 = 40*0.4 = 16
        assert_eq!(admiralty_to_confidence("D", 4), 16);
        // E5 = 20*0.2 = 4
        assert_eq!(admiralty_to_confidence("E", 5), 4);
        // F6 = 0*0.0 = 0
        assert_eq!(admiralty_to_confidence("F", 6), 0);
        // A6 = 100*0.0 = 0
        assert_eq!(admiralty_to_confidence("A", 6), 0);
        // F1 = 0*1.0 = 0
        assert_eq!(admiralty_to_confidence("F", 1), 0);
    }

