    // ── Entity Resolution tests ──────────────────────────────────────

    /// Helper: add a person node with the given name + optional unique props.
    fn add_person(graph: &Value, name: &str, props: Vec<(String, Value)>) -> Value {
        let map_entries: Vec<(Value, Value)> = props
            .into_iter()
            .map(|(k, v)| (Value::String(k), v))
            .collect();
        dispatch_method(
            graph,
            "add_node",
            vec![
                Value::String("person".into()),
                Value::String(name.into()),
                Value::String("A".into()),
                Value::Int(6),
                Value::Map(map_entries),
            ],
        )
        .unwrap()
        .unwrap()
    }

    #[test]
    fn test_entity_resolution_merges_duplicate_name() {
        let graph = dispatch("IntelGraph.new", vec![]).unwrap().unwrap();
        let graph = add_person(&graph, "John Smith", vec![]);
        let graph = add_person(&graph, "john smith", vec![]); // case/whitespace dup
        let report = dispatch_method(&graph, "resolve", vec![]).unwrap().unwrap();
        if let Value::Struct { name, fields } = &report {
            assert_eq!(name, "ResolutionReport");
            let merges = fields.iter().find(|(k, _)| k == "merges").map(|(_, v)| v).unwrap();
            if let Value::Array(m) = merges {
                assert_eq!(m.len(), 1, "one duplicate pair should merge");
            } else {
                panic!("merges should be array");
            }
        }
    }

    #[test]
    fn test_entity_resolution_rejects_conflicting_unique_key() {
        let graph = dispatch("IntelGraph.new", vec![]).unwrap().unwrap();
        // Same name but DIFFERENT registry_no -> hard-constraint conflict.
        let graph = add_person(
            &graph,
            "Acme Corp",
            vec![("registry_no".into(), Value::String("US-12345".into()))],
        );
        let graph = add_person(
            &graph,
            "acme corp",
            vec![("registry_no".into(), Value::String("US-99999".into()))],
        );
        let report = dispatch_method(&graph, "resolve", vec![]).unwrap().unwrap();
        if let Value::Struct { fields, .. } = &report {
            let merges = fields.iter().find(|(k, _)| k == "merges").map(|(_, v)| v).unwrap();
            let rejected = fields.iter().find(|(k, _)| k == "rejected").map(|(_, v)| v).unwrap();
            if let (Value::Array(m), Value::Array(r)) = (merges, rejected) {
                assert_eq!(m.len(), 0, "conflict must NOT merge");
                assert_eq!(r.len(), 1, "conflict must be reported as rejected");
            } else {
                panic!("expected merges/rejected arrays");
            }
        }
    }

    #[test]
    fn test_entity_resolution_same_unique_key_merges() {
        let graph = dispatch("IntelGraph.new", vec![]).unwrap().unwrap();
        // Same email on both nodes (same unique key, same value) -> merge allowed,
        // even though the names differ slightly. Use a low threshold so the
        // shared-email blocking gate dominates the name-similarity gate.
        let graph = add_person(
            &graph,
            "Jane Doe",
            vec![("email".into(), Value::String("jane@example.com".into()))],
        );
        let graph = add_person(
            &graph,
            "Jane A. Doe",
            vec![("email".into(), Value::String("jane@example.com".into()))],
        );
        let report = dispatch_method(&graph, "resolve", vec![Value::Int(70)]).unwrap().unwrap();
        if let Value::Struct { fields, .. } = &report {
            let merges = fields.iter().find(|(k, _)| k == "merges").map(|(_, v)| v).unwrap();
            if let Value::Array(m) = merges {
                assert_eq!(m.len(), 1, "shared email should allow merge");
            } else {
                panic!("merges should be array");
            }
        }
    }

    #[test]
    fn test_entity_resolution_candidate_has_confidence() {
        let graph = dispatch("IntelGraph.new", vec![]).unwrap().unwrap();
        let graph = add_person(&graph, "Robert Johnson", vec![]);
        let graph = add_person(&graph, "Robert Johnson", vec![]); // exact duplicate
        let report = dispatch_method(&graph, "resolve", vec![]).unwrap().unwrap();
        if let Value::Struct { fields, .. } = &report {
            let merges = fields.iter().find(|(k, _)| k == "merges").map(|(_, v)| v).unwrap();
            if let Value::Array(m) = merges {
                assert!(!m.is_empty(), "expected at least one merge candidate");
                let merge = &m[0];
                if let Value::Struct { fields: mf, .. } = merge {
                    let conf = mf.iter().find(|(k, _)| k == "confidence").map(|(_, v)| v).unwrap();
                    assert!(
                        matches!(conf, Value::Float(f) if *f > 0.0 && *f <= 1.0),
                        "confidence should be in (0,1]"
                    );
                } else {
                    panic!("merge should be a struct");
                }
            }
        }
    }

