    #[test]
    fn test_incremental_collector_cold_start_changes() {
        let col = dispatch("IncrementalCollector.new", vec![]).unwrap().unwrap();
        let col = dispatch_method(&col, "register_source", vec![
            Value::String("harris_clerk".into()),
            Value::String("https://example.test/plats".into()),
        ]).unwrap().unwrap();
        // Cold start: no validator stored -> first check reports changed.
        let res = dispatch_method(&col, "check_changed", vec![Value::String("harris_clerk".into())]).unwrap().unwrap();
        if let Value::Struct { fields, .. } = &res {
            let changed = fields.iter().find(|(k, _)| k == "changed").map(|(_, v)| v).unwrap();
            assert!(matches!(changed, Value::Bool(true)), "cold start with no validator should report changed");
        }
    }

    #[test]
    fn test_incremental_collector_etag_no_change() {
        let col = dispatch("IncrementalCollector.new", vec![]).unwrap().unwrap();
        let col = dispatch_method(&col, "register_source", vec![
            Value::String("plats".into()),
            Value::String("https://example.test/plats".into()),
        ]).unwrap().unwrap();
        // First fetch records ETag "abc-1".
        let col = dispatch_method(&col, "record_fetch", vec![
            Value::String("plats".into()),
            Value::String("abc-1".into()),
        ]).unwrap().unwrap();
        // Second sweep with SAME ETag -> not changed (304-equivalent).
        let res = dispatch_method(&col, "check_changed", vec![
            Value::String("plats".into()),
            Value::String("abc-1".into()),
        ]).unwrap().unwrap();
        if let Value::Struct { fields, .. } = &res {
            let changed = fields.iter().find(|(k, _)| k == "changed").map(|(_, v)| v).unwrap();
            let reason = fields.iter().find(|(k, _)| k == "reason").map(|(_, v)| v).unwrap();
            assert!(matches!(changed, Value::Bool(false)), "same ETag should be unchanged");
            assert!(matches!(reason, Value::String(s) if s == "etag-match"));
        }
    }

    #[test]
    fn test_incremental_collector_etag_changed() {
        let col = dispatch("IncrementalCollector.new", vec![]).unwrap().unwrap();
        let col = dispatch_method(&col, "register_source", vec![
            Value::String("plats".into()),
            Value::String("https://example.test/plats".into()),
        ]).unwrap().unwrap();
        let col = dispatch_method(&col, "record_fetch", vec![
            Value::String("plats".into()),
            Value::String("abc-1".into()),
        ]).unwrap().unwrap();
        // Server now returns a NEW ETag -> changed.
        let res = dispatch_method(&col, "check_changed", vec![
            Value::String("plats".into()),
            Value::String("abc-2".into()),
        ]).unwrap().unwrap();
        if let Value::Struct { fields, .. } = &res {
            let changed = fields.iter().find(|(k, _)| k == "changed").map(|(_, v)| v).unwrap();
            assert!(matches!(changed, Value::Bool(true)), "new ETag should report changed");
        }
    }

    #[test]
    fn test_incremental_collector_watermark_and_count() {
        let col = dispatch("IncrementalCollector.new", vec![]).unwrap().unwrap();
        let col = dispatch_method(&col, "register_source", vec![
            Value::String("src".into()),
            Value::String("https://example.test".into()),
        ]).unwrap().unwrap();
        let col = dispatch_method(&col, "record_fetch", vec![
            Value::String("src".into()),
            Value::String("etag-x".into()),
            Value::String("lm-y".into()),
            Value::String("hash-z".into()),
        ]).unwrap().unwrap();
        // Watermark fetch count should now be 1.
        let wm = dispatch_method(&col, "watermark", vec![
            Value::String("src".into()),
            Value::String("fetched_count".into()),
        ]).unwrap().unwrap();
        assert!(matches!(&wm, Value::Int(1)), "fetched_count should be 1, got {wm:?}");
        // changed_count aggregator (0 here, since no change recorded).
        let cc = dispatch_method(&col, "changed_count", vec![]).unwrap().unwrap();
        assert!(matches!(&cc, Value::Int(0)));
    }

