    #[test]
    fn test_osint_analyze_text_extracts_entities() {
        // A text with an email, an IP, a domain, and a threat signal.
        let res = dispatch(
            "osint.analyze_text",
            vec![Value::String(
                "Contact jane@example.com or 192.168.1.5. Visit evil.com. Malware breach detected."
                    .to_string(),
            )],
        )
        .unwrap()
        .unwrap();
        if let Value::Struct { name, fields } = &res {
            assert_eq!(name, "ObservationAnalysis");
            let entities = fields.iter().find(|(k, _)| k == "entities").map(|(_, v)| v).unwrap();
            if let Value::Array(e) = entities {
                let types: std::collections::HashSet<String> = e
                    .iter()
                    .filter_map(|v| match v {
                        Value::Struct { fields: ef, .. } => ef
                            .iter()
                            .find(|(k, _)| k == "entity_type")
                            .and_then(|(_, v)| if let Value::String(s) = v { Some(s.clone()) } else { None }),
                        _ => None,
                    })
                    .collect();
                assert!(types.contains("email"), "should extract email");
                assert!(types.contains("ip"), "should extract ip");
                assert!(types.contains("domain"), "should extract domain");
            } else {
                panic!("entities should be array");
            }
            // Threat signal should push it to high tier.
            let action = fields.iter().find(|(k, _)| k == "action").map(|(_, v)| v).unwrap();
            assert!(matches!(action, Value::String(s) if s == "auto-publish"));
        }
    }

    #[test]
    fn test_osint_analyze_text_low_confidence_routes_to_analyst() {
        // A single weak signal (just one domain) -> low-ish confidence, analyst review.
        let res = dispatch(
            "osint.analyze_text",
            vec![Value::String("seen on example.com".to_string())],
        )
        .unwrap()
        .unwrap();
        if let Value::Struct { fields, .. } = &res {
            let action = fields.iter().find(|(k, _)| k == "action").map(|(_, v)| v).unwrap();
            assert!(
                matches!(action, Value::String(s) if s == "analyst-review"),
                "single weak signal should route to analyst review, got {action:?}"
            );
            let prov = fields.iter().find(|(k, _)| k == "provenance").map(|(_, v)| v).unwrap();
            assert!(matches!(prov, Value::Array(_)), "analysis must carry provenance");
        }
    }

