    #[test]
    fn test_sources_fanout_unknown_source_reported() {
        let res = dispatch(
            "Sources.fanout",
            vec![
                Value::String("example.com".into()),
                Value::String("domain".into()),
                Value::Array(vec![
                    Value::String("whois".into()),
                    Value::String("nonexistent_source".into()),
                ]),
            ],
        )
        .unwrap()
        .unwrap();
        if let Value::Struct { name, fields } = &res {
            assert_eq!(name, "FanoutResult");
            let results = fields.iter().find(|(k, _)| k == "results").map(|(_, v)| v).unwrap();
            if let Value::Array(r) = results {
                // The unknown source must be reported as an ok=false error record
                // without aborting the whole fan-out.
                let has_unknown_err = r.iter().any(|v| matches!(v, Value::Struct { fields: rf, .. }
                    if rf.iter().any(|(k, v)| k == "error" && matches!(v, Value::String(s) if s.contains("unknown source")))));
                assert!(has_unknown_err, "unknown source must be reported, not panics");
            } else {
                panic!("results should be array");
            }
        }
    }

