    #[test]
    fn test_scanner_scan_scope_authorize_valid_cidr() {
        let result = dispatch("ScanScope.authorize", vec![Value::String("192.168.1.0/24".into())]);
        assert!(result.is_some(), "ScanScope.authorize should be dispatched");
        let scope = result.unwrap().unwrap();
        if let Value::Struct { name, fields } = &scope {
            assert_eq!(name, "ScanScope");
            // Should contain cidr, base_ip, mask fields
            assert!(fields.iter().any(|(k, _)| k == "cidr"));
            assert!(fields.iter().any(|(k, _)| k == "base_ip"));
            assert!(fields.iter().any(|(k, _)| k == "mask"));
            // cidr field should match input
            let cidr = fields.iter().find(|(k, _)| k == "cidr").unwrap();
            assert!(matches!(&cidr.1, Value::String(s) if s == "192.168.1.0/24"));
        } else {
            panic!("expected ScanScope struct");
        }
    }

