    #[test]
    fn test_scanner_scan_result_fields() {
        // Create a valid scope for loopback
        let scope = dispatch("ScanScope.authorize", vec![Value::String("127.0.0.1/32".into())])
            .unwrap().unwrap();
        // Scan a port that's unlikely open (just check return shape)
        let result = dispatch("Scanner.scan", vec![
            scope,
            Value::Array(vec![Value::Int(1)]),  // port 1 -- unlikely open
            Value::Int(100),  // 100ms timeout
        ]);
        assert!(result.is_some());
        let scan_results = result.unwrap().unwrap();
        if let Value::Array(arr) = &scan_results {
            // Should have exactly 1 result (1 IP * 1 port)
            assert_eq!(arr.len(), 1);
            if let Value::Struct { name, fields } = &arr[0] {
                assert_eq!(name, "ScanResult");
                assert!(fields.iter().any(|(k, _)| k == "ip"));
                assert!(fields.iter().any(|(k, _)| k == "port"));
                assert!(fields.iter().any(|(k, _)| k == "open"));
                assert!(fields.iter().any(|(k, _)| k == "service"));
            } else {
                panic!("expected ScanResult struct");
            }
        } else {
            panic!("expected Array of ScanResult");
        }
    }

    #[test]
    fn test_scanner_scan_ip_outside_range_returns_err() {
        // Authorize only 10.0.0.0/32
        let scope = dispatch("ScanScope.authorize", vec![Value::String("10.0.0.1/32".into())])
            .unwrap().unwrap();
        // Try scanning 192.168.1.1 which is outside the range
        // Scanner.scan scans the IPs in scope range, so this test verifies
        // that only IPs within the scope are scanned (checked internally).
        // The scan should succeed but only scan 10.0.0.1.
        let result = dispatch("Scanner.scan", vec![
            scope,
            Value::Array(vec![Value::Int(80)]),
            Value::Int(50),
        ]);
        assert!(result.is_some());
        let scan_results = result.unwrap().unwrap();
        if let Value::Array(arr) = &scan_results {
            // All results should have IP within 10.0.0.1/32
            for entry in arr {
                if let Value::Struct { fields, .. } = entry {
                    let ip = fields.iter().find(|(k, _)| k == "ip").unwrap();
                    if let Value::String(s) = &ip.1 {
                        assert_eq!(s, "10.0.0.1", "should only scan authorized IPs");
                    }
                }
            }
        }
    }

    // ── IntelReport tests ────────────────────────────────────────────

    /// Helper: build a small graph with 2 nodes and 1 edge for testing.
    fn make_test_graph() -> Value {
        let graph = dispatch("IntelGraph.new", vec![]).unwrap().unwrap();
        let graph = dispatch_method(
            &graph,
            "add_node",
            vec![
                Value::String("indicator".into()),
                Value::String("malware.com".into()),
                Value::String("A".into()),
                Value::Int(1),
                Value::Map(vec![]),
            ],
        )
        .unwrap()
        .unwrap();
        let graph = dispatch_method(
            &graph,
            "add_node",
            vec![
                Value::String("threat-actor".into()),
                Value::String("APT-42".into()),
                Value::String("B".into()),
                Value::Int(2),
                Value::Map(vec![]),
            ],
        )
        .unwrap()
        .unwrap();

        // Get node IDs for edge
        let nodes_val = dispatch_method(&graph, "nodes", vec![]).unwrap().unwrap();
        let node_ids: Vec<String> = if let Value::Array(nodes) = &nodes_val {
            nodes
                .iter()
                .filter_map(|n| {
                    if let Value::Struct { fields, .. } = n {
                        fields.iter().find(|(k, _)| k == "id").and_then(|(_, v)| {
                            if let Value::String(s) = v { Some(s.clone()) } else { None }
                        })
                    } else {
                        None
                    }
                })
                .collect()
        } else {
            vec![]
        };

        dispatch_method(
            &graph,
            "add_edge",
            vec![
                Value::String(node_ids[0].clone()),
                Value::String(node_ids[1].clone()),
                Value::String("indicates".into()),
                Value::Map(vec![]),
            ],
        )
        .unwrap()
        .unwrap()
    }

