    #[test]
    fn test_intel_report_add_finding() {
        let graph = make_test_graph();
        let report = dispatch(
            "IntelReport.build",
            vec![
                Value::String("Add Finding Test".into()),
                graph,
                Value::Array(vec![]),
            ],
        )
        .unwrap()
        .unwrap();
        let updated = dispatch_method(
            &report,
            "add_finding",
            vec![
                Value::String("New critical finding".into()),
                Value::String("A".into()),
                Value::Int(1),
            ],
        )
        .unwrap()
        .unwrap();
        if let Value::Struct { fields, .. } = &updated {
            let findings = fields.iter().find(|(k, _)| k == "findings").unwrap();
            if let Value::Array(arr) = &findings.1 {
                assert_eq!(arr.len(), 1, "should have 1 finding after add_finding");
                if let Value::Struct { name, fields: ff } = &arr[0] {
                    assert_eq!(name, "Finding");
                    assert!(ff.iter().any(|(k, _)| k == "text"));
                    assert!(ff.iter().any(|(k, _)| k == "confidence"));
                    // A/1 reliability -> Documented tier.
                    assert!(ff.iter().any(|(k, v)| k == "evidence_tier"
                        && matches!(v, Value::String(s) if s == "Documented")));
                }
            } else {
                panic!("findings should be an array");
            }
        }
    }

    #[test]
    fn test_intel_report_evidence_tier_unfalsifiable() {
        let graph = make_test_graph();
        let report = dispatch(
            "IntelReport.build",
            vec![
                Value::String("Tier Test".into()),
                graph,
                Value::Array(vec![]),
            ],
        )
        .unwrap()
        .unwrap();
        // Explicitly declared as unfalsifiable -> must be tagged, NOT rendered as fact.
        let updated = dispatch_method(
            &report,
            "add_finding",
            vec![
                Value::String("A claim with no testable prediction".into()),
                Value::String("C".into()),
                Value::Int(3),
                Value::String("unfalsifiable".into()),
            ],
        )
        .unwrap()
        .unwrap();
        if let Value::Struct { fields, .. } = &updated {
            let findings = fields.iter().find(|(k, _)| k == "findings").unwrap();
            if let Value::Array(arr) = &findings.1 {
                if let Value::Struct { fields: ff, .. } = &arr[0] {
                    let tier = ff.iter().find(|(k, _)| k == "evidence_tier").unwrap();
                    assert!(
                        matches!(&tier.1, Value::String(s) if s == "Unfalsifiable"),
                        "unfalsifiable claim must be tagged, not rendered as fact"
                    );
                }
            } else {
                panic!("findings should be an array");
            }
        }
    }

