    #[test]
    fn test_format_e164_variants() {
        // Already has international prefix 00
        assert_eq!(format_e164("00441234567890", "1").unwrap(), "+441234567890");
        // Leading +
        assert_eq!(format_e164("+14155552671", "1").unwrap(), "+14155552671");
        // NANP full national
        assert_eq!(format_e164("14155552671", "1").unwrap(), "+14155552671");
        // US 10-digit local with default cc 1
        assert_eq!(format_e164("4155552671", "1").unwrap(), "+14155552671");
        // UK local with default cc 44
        assert_eq!(format_e164("2079460958", "44").unwrap(), "+442079460958");
    }

    #[test]
    fn test_e164_country_info() {
        let (cc, name, iso2) = e164_country_info("+14155552671").expect("US");
        assert_eq!(cc, "1");
        assert_eq!(iso2, "US");
        let (cc, _, iso2) = e164_country_info("+447911123456").expect("UK");
        assert_eq!(cc, "44");
        assert_eq!(iso2, "GB");
        // Longest-prefix: +380 Ukraine vs +3 fallback
        let (cc, _, iso2) = e164_country_info("+380501234567").expect("UA");
        assert_eq!(cc, "380");
        assert_eq!(iso2, "UA");
    }

