    #[test]
    fn test_phone_number_mitigation_dispatch() {
        // Mitigation must route, resolve the carrier the dataset assigns, and
        // return a RobocallMitigation struct with carrier + certification fields
        // and an honest snapshot source. It must NOT hard-code a specific
        // carrier's certification, because the real NANPA dataset (not a seed
        // fixture) may assign a different carrier to the number.
        let result = dispatch("PhoneNumber.mitigation", vec![Value::String("512-850-1815".into())]);
        assert!(result.is_some(), "mitigation should be routable");
        let res = result.unwrap().unwrap();
        if let Value::Struct { name, fields } = &res {
            assert_eq!(name, "RobocallMitigation");
            // Structural contract: carrier resolved, certification is a bool,
            // and snapshot_source is present (seed when no snapshot on disk).
            assert!(fields.iter().any(|(k, _)| k == "carrier"));
            assert!(fields.iter().any(|(k, v)| k == "rmdb_certified" && matches!(v, Value::Bool(_))));
            assert!(fields.iter().any(|(k, _)| k == "rmdb_status"));
            assert!(fields.iter().any(|(k, _)| k == "snapshot_source"));
        } else {
            panic!("expected RobocallMitigation struct");
        }
    }

